-- inbound messaging v2, expand (WP-24; _db/messaging.md 4, 5.1, 10.1). Generated by drizzle-kit; hand edits:
--   1. the three inbound_emails indexes drizzle-kit put here moved to 0019 (CONCURRENTLY, no transaction; inbound_emails
--      is a large table);
--   2. every inbound_emails check is added NOT VALID (it still holds every new write); 0019 validates all of them but
--      sender_len_ck and subject_len_ck, which wait for `backfill-inbound` to cut legacy values (owner-actions/WP-24.md).
-- The previous release keeps working on this schema: it writes text_body (now nullable) and kind/application_id only,
-- which every check here allows. The checks it would break (link_reason, classified, offer_needs_rule) are WP-46's.
CREATE TABLE "forwarding_verifications" (
	"user_id" text NOT NULL,
	"provider" text NOT NULL,
	"code" text,
	"confirm_url" text,
	"received_at" timestamp with time zone DEFAULT now() NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"acknowledged_at" timestamp with time zone,
	CONSTRAINT "forwarding_verifications_user_id_provider_pk" PRIMARY KEY("user_id","provider"),
	CONSTRAINT "forwarding_verifications_provider_ck" CHECK (provider IN ('gmail')),
	CONSTRAINT "forwarding_verifications_payload_ck" CHECK (code IS NOT NULL OR confirm_url IS NOT NULL),
	CONSTRAINT "forwarding_verifications_code_ck" CHECK (code IS NULL OR code ~ '^[0-9]{6,12}$'),
	CONSTRAINT "forwarding_verifications_url_ck" CHECK (confirm_url IS NULL OR (confirm_url ~ '^https://' AND char_length(confirm_url) <= 2048)),
	CONSTRAINT "forwarding_verifications_expiry_ck" CHECK (expires_at > received_at)
);
